<?php
session_start();
$pdo=new PDO('mysql:host=127.0.0.1;dbname=sql_pesonatari_site;charset=utf8mb4','sql_pesonatari_site','dcbf4afe83baa8',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
if(isset($_GET['ajax'])&&$_GET['ajax']==='tari'){ $q='%'.trim($_GET['q']??'').'%';$st=$pdo->prepare('SELECT id,nama_tari,provinsi,kategori,gambar FROM tari WHERE nama_tari LIKE ? ORDER BY id DESC LIMIT 12');$st->execute([$q]);header('Content-Type: application/json');echo json_encode($st->fetchAll());exit; }
if($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals($_SESSION['csrf'],$_POST['csrf']??''))exit('Invalid CSRF');
if(isset($_POST['vote'])){$pdo->prepare('INSERT INTO vote(tari_id,session_key) VALUES(?,?)')->execute([(int)$_POST['tari_id'],session_id()]);header('Location:index.php#vote');exit;}
if(isset($_POST['fav'])){$pdo->prepare('INSERT INTO favorit(tari_id,session_key) VALUES(?,?)')->execute([(int)$_POST['tari_id'],session_id()]);header('Location:index.php#tari');exit;}
$popular=$pdo->query('SELECT * FROM tari ORDER BY id DESC LIMIT 6')->fetchAll();
$events=$pdo->query('SELECT * FROM event ORDER BY tanggal ASC LIMIT 6')->fetchAll();
$votes=$pdo->query('SELECT t.nama_tari,COUNT(v.id) c FROM tari t LEFT JOIN vote v ON v.tari_id=t.id GROUP BY t.id ORDER BY c DESC LIMIT 5')->fetchAll();
