<script>
const cd=document.getElementById('cd');setInterval(()=>{const d=new Date(cd.dataset.date)-new Date();cd.textContent=d<=0?'Hari Tari Nasional dimulai!':Math.floor(d/86400000)+' hari '+Math.floor((d%86400000)/3600000)+' jam'},1000);
document.querySelectorAll('.prov').forEach(p=>p.onclick=()=>mapInfo.textContent='Pulau '+p.dataset.name+': tampilkan tari khas, festival, dan statistik mingguan.');
const data={Sumatera:['Tari Saman & Piring','Gerak kolektif dan energi adat'],Jawa:['Tari Serimpi','Elegan, filosofis, berakar keraton'],Kalimantan:['Tari Hudoq','Ritual Dayak penuh makna'],Sulawesi:['Tari Pakarena','Lembut dan sakral'],Bali:['Tari Kecak','Dramatik vokal cak'],Papua:['Tari Yospan','Persaudaraan dan sukacita']};
function paint(r){preview.innerHTML=`<h3>${r}</h3><p>${data[r][0]}</p><p>${data[r][1]}</p><a href='#tari' class='btn btn-c'>Lihat Detail Tari</a>`;}paint('Sumatera');document.querySelectorAll('#tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');paint(b.dataset.r);});
const io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('show')), {threshold:.12});document.querySelectorAll('.reveal').forEach(e=>io.observe(e));
search?.addEventListener('input',async()=>{const r=await fetch('index.php?ajax=tari&q='+encodeURIComponent(search.value));const d=await r.json();tariList.innerHTML=d.map(x=>`<article class='card'><img src='${x.gambar}'><div style='padding:14px'><h3>${x.nama_tari}</h3><small>${x.provinsi} • ${x.kategori}</small></div></article>`).join('')})
</script></body></html>
